<?php
namespace Nakhostin\PerformanceEngine\Optimization;
final class OptimizationManifestStorage { public const OPTION = 'npe_optimization_manifests'; private const LIMIT = 100; public function save( OptimizationManifest $manifest ): bool { $url = $this->normalize( $manifest->source_url() ); if ( '' === $url ) { return false; } $all = get_option( self::OPTION, array() ); $all = is_array( $all ) ? $all : array(); $all[ hash( 'sha256', $url ) ] = $manifest->to_array(); return update_option( self::OPTION, array_slice( $all, -self::LIMIT, null, true ), false ); } public function for_url( string $url ): ?OptimizationManifest { $all = get_option( self::OPTION, array() ); $data = is_array( $all ) ? ( $all[ hash( 'sha256', $this->normalize( $url ) ) ] ?? null ) : null; return is_array( $data ) ? OptimizationManifest::from_array( $data ) : null; } public function flush(): bool { return delete_option( self::OPTION ); } public function invalidate_url( string $url ): bool { $all = get_option( self::OPTION, array() ); if ( ! is_array( $all ) ) { return false; } unset( $all[ hash( 'sha256', $this->normalize( $url ) ) ] ); return update_option( self::OPTION, $all, false ); } private function normalize( string $url ): string { $parts = wp_parse_url( esc_url_raw( $url ) ); if ( ! is_array( $parts ) || empty( $parts['host'] ) ) { return ''; } return strtolower( (string) ( $parts['scheme'] ?? 'https' ) ) . '://' . strtolower( (string) $parts['host'] ) . '/' . ltrim( (string) ( $parts['path'] ?? '/' ), '/' ); } }
